for n in ['portada-rayos.jpg','producto-kit.jpg','ventaja-unidad.jpg','proceso-3.jpg','cierre-premium.jpg']:
 shutil.copy(ROOT/'fase-3/generador/assets'/n,img/n)
for n in ['logo-claro.png','logo-oscuro.png']:
 shutil.copy(ROOT/'lumine-presentaciones/fase4/img'/n,img/n)

def label(t):return f'<div class="label">{t}</div>'
def num(v,t,sub=''):return f'<div class="stat"><strong>{v}</strong>{label(t)}<p>{sub}</p></div>'
def row(a,b,c=''):return f'<div class="row"><b>{a}</b><span>{b}</span><small>{c}</small></div>'
def title(a,b=''):return f'<h1>{a}</h1>'+ (f'<div class="lead">{b}</div>' if b else '')
def content(s):
 k=s['id']
 if k=='gancho':return '<div class="hook"><div class="kicker">LUMINE MOTORS / ESTIMADOR DE AHORRO CON IA</div><h1>¿CUÁNTO<br>TE VAS A<br><em>AHORRAR?</em></h1><div class="hook-bottom"><span>Una estimación personal.<br>Una promesa verificable.</span><span>Diego Alarcón · Benjamín Torres · Lukas Verdugo<br>Prof. Cristián R. Cisterna-Aravena<br>IA Aplicada al Marketing y los Negocios · NRC 4153</span></div><div class="vertical">ESTIMAR → EXPLICAR → COMPROBAR</div></div>'
 if k=='error':return title('UNA CIFRA PARA TODOS<br><em>se equivoca.</em>')+f'<div class="chart-two"><div>{label("ERROR MEDIO · PUNTOS PORCENTUALES")}<div class="barrow"><span>Cifra genérica 25%</span><b>7,90</b><i style="width:100%"></i></div><div class="barrow final"><span>Modelo Ridge</span><b>0,77</b><i style="width:9.75%"></i></div></div><aside>{num("≈10×","MENOS ERROR","Dentro de la evaluación simulada.")}</aside></div><div class="stamp">EVIDENCIA COMPUTACIONAL · NO ES AHORRO MEDIDO</div>'
 if k=='evidencia':return title('CONDUCIR ES REAL.<br><em>El ahorro se simula.</em>')+'<div class="three">'+num('300','CONDUCTORES SINTÉTICOS','Entrenamiento y prueba.<br>Dos semanas por conductor.')+num('45','JORNADAS REALES SECUNDARIAS','Conducción de 21 vehículos.<br>Ahorro calculado por simulación.')+num('0','KITS CON AHORRO MEDIDO','La validación física<br>sigue pendiente.')+'</div><div class="bottom-line">Terreno propio eliminado del alcance · Datos externos de otra ciudad</div>'
 if k=='pregunta':return title('PODEMOS ESTIMAR.<br><em>Falta probar si vende.</em>')+'<div class="split-question"><div><div class="step">01 / PRECISIÓN</div><h2>Evidencia<br>computacional</h2><p>Modelo, prototipo y reglas<br>de gobernanza desarrollados.</p></div><div><div class="step">02 / ADOPCIÓN</div><h2>Efecto comercial<br>pendiente</h2><p>H3 se contrasta en un A/B.<br>Implementación por fases.</p></div></div>'
 if k=='arquitectura':return title('CADA CIFRA SE CALCULA<br><em>una sola vez.</em>')+'<div class="pipeline">'+''.join(f'<div><span class="step">0{i+1}</span><h2>{a}</h2><p>{b}</p></div>'for i,(a,b)in enumerate([('SIMULAR','Energía recuperable'),('PREDECIR','Ridge · 11 variables'),('TRADUCIR','Pesos y plazo'),('EXPLICAR','Claude + RAFA')]))+'</div><div class="gate"><b>VALI­DADOR + TÉCNICO</b><span>Las cifras llegan cerradas al lenguaje.</span></div><div class="bottom-line">La IA generativa copia y explica; cualquier salida inválida vuelve a una plantilla.</div>'
 if k=='caso':return '<div class="kicker">CASO N1 / COLECTIVO DE 213 KM AL DÍA</div><div class="case"><div class="hero-number">19,7<span>%</span></div><div class="case-label">AHORRO ESTIMADO</div><div class="range"><span>18,4%</span><i><b></b></i><span>21,0%</span></div><div class="case-stats">'+num('$159.000','POR MES')+num('22','MESES · CONSERVADOR')+'</div></div><div class="stamp">CASO SINTÉTICO · SUPUESTOS DEL RAMO IA · PLANTILLA DE RESPALDO</div>'
 if k=='cobertura':return title('EL INTERVALO TAMBIÉN<br><em>tiene que aprobar.</em>')+'<div class="coverage"><div class="cover-val"><strong>36<span>%</span></strong><p>Entrenamiento<br>solo sintético</p></div><div class="cover-mid"><span>REAJUSTE CON<br>DATOS REALES</span><b>→</b></div><div class="cover-val"><strong>78<span>%</span></strong><p>Tras incorporar<br>datos reales</p></div><div class="target"><strong>80%</strong><span>COBERTURA<br>OBJETIVO</span></div></div><div class="bottom-line">Mejora la transferencia. Falta comprobarla con telemetría de Santiago.</div>'
 if k=='rafa':return title('LAS INSTRUCCIONES<br><em>también se probaron.</em>')+'<div class="rafa-layout"><div class="versions">'+''.join(f'<div><div class="vbar" style="height:{max(n/12*280,5)}px"></div><b>{n}/12</b><span>{v}</span></div>'for n,v in [(0,'v1'),(4,'v2'),(11,'v3'),(12,'v3.1')])+'</div><aside>'+num('10/10','ATAQUES RESISTIDOS','Resultado tras revisión humana.')+'<p class="limit">Una ejecución por caso.<br>La batería se repite ante cambios.</p></aside></div><div class="bottom-line">RAFA: rol · acción · formato · antecedentes</div>'
 if k=='trazabilidad':return title('CADA CAMBIO<br><em>deja una huella.</em>')+'<div class="trace"><div class="agents"><div><span class="step">CONSTRUCCIÓN</span><h2>Claude Code</h2><p>Simulador, prototipo e informes.</p></div><div><span class="step">INTEGRACIÓN</span><h2>Codex</h2><p>Ridge, pruebas y reproducción.</p></div><div class="human">EQUIPO → REVISA E INTEGRA</div></div><div class="proof">'+num('20/20','PRUEBAS AUTOMÁTICAS','En la integración documentada.')+'<div class="mini-rule">Cinco IA auditoras.<br>Cada hallazgo se contrasta.</div></div></div>'
 if k=='gobernanza':return title('UNA PERSONA<br><em>conserva la decisión.</em>')+'<div class="three controls"><div><span class="step">01</span><h2>PROTEGER</h2><p>Consentimiento.<br>Ruta borrada.<br>Variables agregadas.</p></div><div><span class="step">02</span><h2>SUPERVISAR</h2><p>El técnico aprueba,<br>ajusta con motivo<br>o bloquea.</p></div><div><span class="step">03</span><h2>DETENER</h2><p>Error, cobertura,<br>brechas, fallas<br>o reclamos.</p></div></div><div class="bottom-line">Legalidad, garantía y financiamiento: respuesta humana por escrito.</div>'
 if k=='economia':return title('EL PILOTO DEBE JUSTIFICAR<br><em>la inversión.</em>')+'<div class="economy"><div class="eco-main">'+num('+3,0','PUNTOS DE AGENDAMIENTO','Equilibrio aproximado, condicionado<br>a los supuestos del informe.')+'</div><div class="eco-side">'+num('$9,0 M','COSTO DEL PRIMER AÑO')+num('68%','ROI CON +5 PP','Escenario; efecto aún no medido.')+'</div></div><div class="stamp">A/B PROPUESTO: DETECTA +15 PP · NO ESTÁ DIMENSIONADO PARA +3 PP</div>'
 if k=='cierre':return '<div class="kicker">RECOMENDACIÓN / IMPLEMENTAR CON AJUSTES</div><h1 class="closing">UNA PROMESA<br>QUE SE PUEDE<br><em>COMPROBAR.</em></h1><div class="closing-actions"><div><b>01</b><span>Retirar la cifra<br>genérica</span></div><div><b>02</b><span>Medir el efecto<br>con un A/B</span></div><div><b>03</b><span>Verificar antes<br>de escalar</span></div></div><div class="closing-tail">Estimación transparente · Telemetría · Viabilidad técnica y regulatoria</div>'
 if k=='objetivos':return title('QUÉ RESPONDIMOS<br><em>y qué sigue pendiente.</em>')+'<div class="table">'+row('OE1 · Datos propios','No cumplido; sustituido','45 jornadas secundarias')+row('OE2 · Modelo','Cumplido en evaluación','MAE ≤3 pp; R² ≥0,80')+row('OE3 · Prototipo','Cumplido en batería','12/12 casos; 10/10 ataques')+row('OE4 · Cliente','Rediseñado, sin medición','A/B de 173 por grupo')+row('OE5 · Gobernanza','Regla y responsables definidos','Cinco gatillos de suspensión')+'</div><div class="bottom-line">H1 reformulada · H2 parcial: cuatro variables explican 73%; once, 83% · H3 pendiente</div>'
 if k=='modelos':return title('LA EVIDENCIA<br><em>detrás del modelo.</em>')+'<div class="bench">'+''.join(f'<div><span>{a}</span><div class="track"><i style="width:{v/7.9*100}%"></i></div><b>{str(v).replace(".",",")} pp</b></div>'for a,v in [('Genérica 25%',7.9),('ICCT 15,5%',2.3),('Promedio por perfil',1.08),('GBM · 11 variables',.89),('Ridge · 11 variables',.77)])+'</div><div class="bottom-line">Ridge: 0,77 ± 0,08 pp · R² 0,83 · Cobertura 81% en sintéticos</div>'
 if k=='prompt':return title('RAFA: DEL DATO CERRADO<br><em>al mensaje.</em>')+'<div class="prompt-grid"><div class="json"><span>ENTRADA REGISTRADA · E3</span><pre>{\n  "estado": "ok",\n  "ahorro": "19,6%",\n  "intervalo": "18,2% a 21,0%",\n  "ahorro_mensual": "$158.000",\n  "plazo_conservador": "22 meses"\n}</pre></div><div class="rules"><div><b>R</b><span>Asesor técnico</span></div><div><b>A</b><span>Copiar; nunca calcular</span></div><div><b>F</b><span>JSON por esquema</span></div><div><b>A</b><span>Reglas y ejemplos</span></div><p>Validador de nueve criterios.<br>Plantilla ante una salida inválida.</p></div></div><div class="bottom-line">El ejemplo registrado usa cifras de E3; el MVP actual usa Ridge y plantilla de respaldo.</div>'
 if k=='supuestos':return title('EL RETORNO<br><em>depende de supuestos.</em>')+'<div class="table compact">'+row('Cotizaciones / año','1.000','S13')+row('Agendamiento inicial','30%','S14')+row('Diagnóstico → instalación','40%','S15')+row('Margen por instalación','$756.300','30% de $2.521.000 netos · S7/S16')+row('Costo primer año','$9.005.200','Incluye revisión técnica con 350 diagnósticos')+'</div><div class="calc">+1 pp → 1.000 × 0,01 × 0,40 × $756.300 = $3.025.200</div><div class="bottom-line">Presupuesto del escenario base. Revisar costo variable y potencia estadística para el umbral de +3 pp.</div>'
 if k=='suspension':return title('CUÁNDO SE DETIENE<br><em>el diagnóstico.</em>')+'<div class="table triggers">'+row('ERROR','Mediana absoluta >3 pp','Últimas 20 instalaciones verificadas')+row('COBERTURA','Por debajo de 70%','Últimas 30 verificadas')+row('EQUIDAD','Brecha entre perfiles >15 pp','Cobertura por perfil')+row('CALIDAD','>5% de fallas semanales','O una falla en la batería tras un cambio')+row('RECLAMO','Un reclamo fundado','Por la promesa de ahorro')+'</div>'
 raise ValueError(k)

