CSS += CSS_VISUAL
slides=[]
for i,s in enumerate(S):
 s['words']=len(re.findall(r'\b[\wÁÉÍÓÚáéíóúñ]+\b',re.sub(r'\[[^]]*\]','',s.get('script',''))))
 s['seconds']=round(s['words']/130*60+1.2+(3.5 if i==0 else 0)+s.get('demo',0)+s.get('script','').count('[Clic:')*1.2,1) if i<12 else 0
 slides.append(f'<section class="slide {"dark" if s["dark"] else ""}" id="s{i+1}"><header class="header"><img class="brand" src="img/{"logo-claro.png" if s["dark"] else "logo-oscuro.png"}" alt="Lumine"><span class="right">{s.get("annex",f"{i+1:02d}")} / IA APLICADA · NRC 4153</span></header><main class="body">{visual(s,content)}</main><footer class="source">{E(s["source"])}</footer><span class="page">{s.get("annex",f"{i+1:02d}")}</span></section>')
(OUT/'laminas.html').write_text('<!doctype html><html lang="es"><meta charset="utf-8"><title>Lumine · IA aplicada · Láminas</title><style>'+CSS+'</style><body>'+''.join(slides)+'</body></html>')
(OUT/'contenido.json').write_text(json.dumps(D,ensure_ascii=False,indent=2))
print(len(S),'láminas; segundos previstos',round(sum(s['seconds']for s in S[:12]),1))
